class Solution {
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        return build(inorder, 0, inorder.length, postorder, 0, postorder.length);
    }

    private TreeNode build(int[] inorder, int inStart, int inEnd, int[] postorder, int postStart, int postEnd) {
        if (inStart >= inEnd) {
            return null;
        }
        int rootValue = postorder[postEnd - 1];
        int split = inStart;
        while (inorder[split] != rootValue) {
            split++;
        }
        int leftSize = split - inStart;
        TreeNode root = new TreeNode(rootValue);
        root.left = build(inorder, inStart, split, postorder, postStart, postStart + leftSize);
        root.right = build(inorder, split + 1, inEnd, postorder, postStart + leftSize, postEnd - 1);
        return root;
    }
}

